 * Tokenizer module for converting various input types to standardized string
 * tokens. Idiomatic Scala 2.13 translation of the original Python module.
 *
 * Design notes
 *  - Immutability is the default. `Token`, `TokenType`, etc. are all
 *    immutable case classes / case objects.
 *  - Absence is modelled with `Option`, errors with `Either` / `Try`.
 *  - Runtime dispatch (Python's duck typing) becomes pattern matching and
 *    type classes (`Numeric`, `Tokenizable`).
 *  - Where Python relied on ad-hoc union types (`str | bytes`,
 *    `datetime | date`, ...) we use small sealed ADTs.
 */

import java.time.format.DateTimeFormatter
import java.time.{LocalDate, LocalDateTime}
import java.nio.charset.{Charset, StandardCharsets}

import scala.collection.mutable
import scala.util.Try

// ============================================================================
// Enums
// ============================================================================

sealed abstract class TokenType(val value: String)

object TokenType {
  case object STRING     extends TokenType("string")
  case object NUMERIC    extends TokenType("numeric")
  case object TEMPORAL   extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY     extends TokenType("binary")
  case object NULL       extends TokenType("null")

  val values: Seq[TokenType] =
    Seq(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)
}

// ============================================================================
// Structural typing → type class
// ============================================================================

/** Any type that knows how to render itself as a token string. */
trait Tokenizable[-A] {
  def toToken(value: A): String
}

// ============================================================================
// Core Token model
// ============================================================================

final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {

  /** Return a new token whose metadata is augmented with `entries`. */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries)
}

/**
 * Mutable batch of tokens - retained to mirror the Python API. Prefer working
 * with plain `Seq[Token]` in new code.
 */
final class MutableTokenBatch {
  private val buffer   = mutable.ArrayBuffer.empty[Token]
  private var _closed  = false

  def tokens: Seq[Token] = buffer.toSeq
  def isProcessed: Boolean = _closed

  def add(token: ***REDACTED*** Unit = {
    if (_closed) throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = _closed = true
}

// ============================================================================
// Generic containers (variance)
// ============================================================================

/** Covariant container - can produce values of subtypes of `A`. */
final class TokenContainer[+A](items: Seq[A]) {
  private val underlying: Vector[A] = items.toVector

  def getAll: Vector[A]                     = underlying
  def mapTokens(f: A => String): List[String] = underlying.iterator.map(f).toList
}

/** Contravariant sink - can consume values of supertypes of `A`. */
final class TokenSink[-A] {
  private val received = mutable.ArrayBuffer.empty[Any]

  def receive(item: A): Unit = received += item

  def drain(): List[Any] = {
    val snapshot = received.toList
    received.clear()
    snapshot
  }
}

/** Invariant handler - exact type required. */
final class BivariantHandler[A](default: A) {
  private var current: A = default

  def get: A             = current
  def set(value: A): Unit = current = value

  def transform(f: A => A): A = {
    current = f(current)
    current
  }
}

// ============================================================================
// Tokenizer hierarchy
// ============================================================================

/** Abstract tokenizer with a generic input type. */
abstract class BaseTokenizer[A] {

  /** Convert a single value to a `Token`. */
  def tokenize(value: A): Token

  /** Lazily tokenize a batch of values. */
  def tokenizeBatch(values: IterableOnce[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

// ----------------------------------------------------------------------------
// StringTokenizer: `str | bytes` becomes a small sealed ADT.
// ----------------------------------------------------------------------------

sealed trait StringOrBytes
object StringOrBytes {
  final case class Str(value: String)          extends StringOrBytes
  final case class Bytes(value: Array[Byte])   extends StringOrBytes

  implicit def fromString(s: String): StringOrBytes         = Str(s)
  implicit def fromBytes(bs: Array[Byte]): StringOrBytes    = Bytes(bs)
}

final class StringTokenizer(
    val encoding: Charset            = StandardCharsets.UTF_8,
    val normalizer: String => String = identity
) extends BaseTokenizer[StringOrBytes] {

  def tokenize(value: StringOrBytes): Token = ***REDACTED***
    val raw = value match {
      case StringOrBytes.Str(s)    => s
      case StringOrBytes.Bytes(bs) => new String(bs, encoding)
    }
    Token(normalizer(raw), TokenType.STRING)
  }
}

// ----------------------------------------------------------------------------
// NumericTokenizer: use the stdlib `Numeric` type class instead of a fixed
// TypeVar union.  Immutable default metadata (Python's mutable default is a
// bug that doesn't have to survive translation).
// ----------------------------------------------------------------------------

final class NumericTokenizer[A](
    val precision: Int                = 6,
    val formatOptions: Map[String, Any] = Map.empty
)(implicit num: Numeric[A]) extends BaseTokenizer[A] {

  def tokenize(value: A): Token = ***REDACTED***
    val text = value match {
      case bd: BigDecimal => bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case d: Double      => f"$d%.${precision}f"
      case f: Float       => f"$f%.${precision}f"
      case other          => num.toDouble(other) match {
        case whole if whole.isValidInt && other.isInstanceOf[Int] => other.toString
        case _                                                    => other.toString
      }
    }
    Token(text, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

// ----------------------------------------------------------------------------
// TemporalTokenizer: `datetime | date` becomes a sealed ADT.
// ----------------------------------------------------------------------------

sealed trait Temporal
object Temporal {
  final case class Date(value: LocalDate)         extends Temporal
  final case class DateTime(value: LocalDateTime) extends Temporal

  implicit def fromDate(d: LocalDate): Temporal         = Date(d)
  implicit def fromDateTime(dt: LocalDateTime): Temporal = DateTime(dt)
}

object TemporalTokenizer {
  val IsoFormat: DateTimeFormatter  = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  val DateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
}

final class TemporalTokenizer(val format: Option[DateTimeFormatter] = None)
    extends BaseTokenizer[Temporal] {

  def tokenize(value: Temporal): Token = ***REDACTED***
    val text = value match {
      case Temporal.DateTime(dt) =>
        format.getOrElse(TemporalTokenizer.IsoFormat).format(dt)
      case Temporal.Date(d) =>
        format.getOrElse(TemporalTokenizer.DateFormat).format(d)
    }
    Token(text, TokenType.TEMPORAL)
  }
}

// ----------------------------------------------------------------------------
// UniversalTokenizer: Python's `isinstance` chain becomes pattern matching.
// ----------------------------------------------------------------------------

final class UniversalTokenizer {
  private val stringTokenizer   = new StringTokenizer()
  private val intTokenizer      = new NumericTokenizer[Long]()
  private val doubleTokenizer   = new NumericTokenizer[Double]()
  private val bigDecTokenizer   = new NumericTokenizer[BigDecimal]()
  private val temporalTokenizer = new TemporalTokenizer()

  /** Dispatch to the right tokenizer based on the runtime type of `value`. */
  def tokenize(value: Any): Token = ***REDACTED*** match {
    case null                       => Token("NULL", TokenType.NULL)
    case None                       => Token("NULL", TokenType.NULL)
    case s: String                  => stringTokenizer.tokenize(StringOrBytes.Str(s))
    case bs: Array[Byte]            => stringTokenizer.tokenize(StringOrBytes.Bytes(bs))
    case i: Int                     => intTokenizer.tokenize(i.toLong)
    case l: Long                    => intTokenizer.tokenize(l)
    case d: Double                  => doubleTokenizer.tokenize(d)
    case f: Float                   => doubleTokenizer.tokenize(f.toDouble)
    case bd: BigDecimal             => bigDecTokenizer.tokenize(bd)
    case bd: java.math.BigDecimal   => bigDecTokenizer.tokenize(BigDecimal(bd))
    case dt: LocalDateTime          => temporalTokenizer.tokenize(Temporal.DateTime(dt))
    case d: LocalDate               => temporalTokenizer.tokenize(Temporal.Date(d))
    case other                      => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  /**
   * Overload for values whose type provides a `Tokenizable` instance - the
   * type-class equivalent of Python's `Tokenizable` Protocol.
   */
  def tokenize[A](value: A)(implicit ev: Tokenizable[A]): Token =
    Token(ev.toToken(value), TokenType.STRUCTURED)
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

final class WhitespaceTokenizer(
    val lowercase: Boolean        = false,
    val minLength: Int            = 0,
    val maxLength: Option[Int]    = None,
    val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(raw: String): Option[String] = {
    val stripped   = if (stripPunctuation) raw.dropWhile(punctuation).reverse.dropWhile(punctuation).reverse else raw
    val cased      = if (lowercase) stripped.toLowerCase else stripped
    val truncated  = maxLength.fold(cased)(m => if (cased.length > m) cased.substring(0, m) else cased)
    if (truncated.length < minLength || truncated.isEmpty) None else Some(truncated)
  }

  def tokenize(text: String): List[Token] =
    text.split("\\s+").iterator
      .filter(_.nonEmpty)
      .zipWithIndex
      .flatMap { case (word, i) =>
        processToken(word).map { processed =>
          Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
        }
      }
      .toList

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /** Returns tokens paired with their `(start, end)` positions in `text`. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)

    words
      .foldLeft((List.empty[(String, Int, Int)], 0)) { case ((acc, cursor), word) =>
        val start = text.indexOf(word, cursor)
        val end   = start + word.length
        val next  = processToken(word).fold(acc)(p => (p, start, end) :: acc)
        (next, end)
      }
      ._1
      .reverse
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Fluent builder
// ============================================================================

final class TokenizerBuilder[A] private (
    private val normalizers: Vector[String => String],
    private val validators:  Vector[A => Boolean],
    private val metadata:    Map[String, Any]
) {

  def withNormalizer(f: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder[A](normalizers :+ f, validators, metadata)

  def withValidator(f: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder[A](normalizers, validators :+ f, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder[A](normalizers, validators, metadata ++ entries)

  /** Build a plain function `A => Token`. Snapshots the current state. */
  def build: A => Token = ***REDACTED***
    val ns = normalizers
    val vs = validators
    val md = metadata

    value => {
      vs.find(v => !v(value))
        .foreach(_ => throw new IllegalArgumentException(s"Validation failed for $value"))
      val text = ns.foldLeft(value.toString)((s, n) => n(s))
      Token(text, TokenType.STRING, md)
    }
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] =
    new TokenizerBuilder[A](Vector.empty, Vector.empty, Map.empty)
}
