object TokenizerTest {
  def main(args: Array[String]): Unit = {
    // Token + withMetadata
    val t = Token("hi", TokenType.STRING).withMetadata("k" -> 1, "j" -> "x")
    assert(t.metadata == Map("k" -> 1, "j" -> "x"), s"metadata: ${t.metadata}")

    // StringTokenizer
    val st = new StringTokenizer(normalizer = _.toUpperCase)
    assert(st.tokenize(StringOrBytes.Str("abc")).value == "ABC")
    assert(st.tokenize(StringOrBytes.Bytes("hey".getBytes("UTF-8"))).value == "HEY")

    // NumericTokenizer
    val nt = new NumericTokenizer[Double](precision = 3)
    assert(nt.tokenize(1.23456).value == "1.235", nt.tokenize(1.23456).value)
    val nti = new NumericTokenizer[Int]()
    assert(nti.tokenize(42).value == "42")

    // TemporalTokenizer
    val tt = new TemporalTokenizer()
    assert(tt.tokenize(Temporal.Date(LocalDate.of(2024, 1, 15))).value == "2024-01-15")
    assert(tt.tokenize(Temporal.DateTime(LocalDateTime.of(2024, 1, 15, 10, 30, 0))).value == "2024-01-15T10:30:00")

    // UniversalTokenizer
    val ut = new UniversalTokenizer()
    assert(ut.tokenize(null).tokenType == TokenType.NULL)
    assert(ut.tokenize("hello").tokenType == TokenType.STRING)
    assert(ut.tokenize(3.14).tokenType == TokenType.NUMERIC)
    assert(ut.tokenize(LocalDate.of(2024, 1, 1)).tokenType == TokenType.TEMPORAL)

    // Tokenizable type class
    case class Foo(x: Int)
    implicit val fooTok: Tokenizable[Foo] = (v: Foo) => s"foo(${v.x})"
    val fooToken = ***REDACTED***
    assert(fooToken.value == "foo(7)" && fooToken.tokenType == TokenType.STRUCTURED, fooToken.toString)

    // WhitespaceTokenizer
    val wt = new WhitespaceTokenizer(lowercase = true, minLength = 2, stripPunctuation = true)
    val toks = wt.tokenize("Hello, World! a is Great.")
    val values = toks.map(_.value)
    // "a" is filtered (len < 2), commas/exclamation stripped
    assert(values == List("hello", "world", "is", "great"), values.toString)
    val pos = wt.tokenizeWithPositions("Hi there")
    assert(pos == List(("hi", 0, 2), ("there", 3, 8)), pos.toString)

    // tokenizeBatch
    val batch = st.tokenizeBatch(List[StringOrBytes](StringOrBytes.Str("a"), StringOrBytes.Str("b"))).toList
    assert(batch.map(_.value) == List("A", "B"))

    // TokenizerBuilder
    val f = TokenizerBuilder[Int]()
      .withValidator(_ >= 0)
      .withNormalizer(_ + "!")
      .withMetadata("src" -> "test")
      .build
    val bt = f(5)
    assert(bt.value == "5!" && bt.metadata("src") == "test")
    try {
      f(-1); assert(false, "should have thrown")
    } catch { case _: IllegalArgumentException => () }

    println("All tests passed.")
  }
}
